pre-actions.script:
                    if (!darpan.facade.common.TenantAccessSupport.isSuperAdmin(ec)) {
                        if (ec.web != null) {
                            // Denial strategy: write a 403 response body directly and then suppress the
                            // Moqui render pipeline via sri.dontDoRender = true.  A redirect (sendRedirect)
                            // would emit HTTP 302 and silently override the 403 we just set, so we must
                            // write inline.  Moqui exposes no public stopRender() API, so we write the
                            // framework field directly — FORWARD-RISK: if the render path ever becomes a
                            // Groovy sandbox or makes ScreenRenderImpl fields private, this will break
                            // silently at runtime rather than compile time; revisit when upgrading
                            // moqui-framework past the current pinned version.
                            ec.web.response.setStatus(403)
                            ec.web.response.setContentType("text/html")
                            ec.web.response.setCharacterEncoding("UTF-8")
                            ec.web.response.writer.write("""<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><title>Access Denied</title>
<link rel="stylesheet" href="/apps/darpan/theme-library/css/tokens.css">
<link rel="stylesheet" href="/apps/darpan/theme-library/css/components.css">
</head><body class="dt-shell"><div class="dt-container">
<div class="error-state" role="alert"><h3 class="error-state__title">super-admin access required</h3>
<p class="error-state__msg">these administration screens are limited to super-admin users — head back to the app to keep working</p>
</div></div></body></html>""")
                            ec.web.response.writer.flush()
                        }
                        sri.dontDoRender = true
                    }
